$apps = Get-AzWebApp

foreach ($app in $apps) {
    if ($app.State -ne 'Running') {
        $body = "App '$($app.Name)' is in state: $($app.State)"
        Send-MailMessage -To 'ops@contoso.com' -From 'alerts@contoso.com' -Subject "App Service Down: $($app.Name)" -Body $body -SmtpServer 'smtp.contoso.com'
    }
}
